-spec crypto_aead_aegis128l_example(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
crypto_aead_aegis128l_example(_Config) ->
    _ = begin
        Key = libsodium_crypto_aead_aegis128l:keygen(),
        Nonce = libsodium_randombytes:buf(libsodium_crypto_aead_aegis128l:npubbytes()),
        Ciphertext = libsodium_crypto_aead_aegis128l:encrypt(<<"message">>, <<"header">>, Nonce, Key),
