-spec crypto_aead_aegis128l_known_answer(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
crypto_aead_aegis128l_known_answer(_Config) ->
    _ = begin
        K = binary:decode_hex(<<"e343d75de99e6d73543968437d3dcf6a">>),
        N = binary:decode_hex(<<"317a5808ed5debf6f527a780e0896b2d">>),
        M = binary:decode_hex(<<"247045cb40dea9c514a885444c526ac867b1b80e4728a23b63f596">>),
        AD = binary:decode_hex(<<"323094c01e">>),
        C = binary:decode_hex(<<"18cb5d2fc5e27bdda5ba16f1320da42049759368548e5bd96f2dbc">>),
        MAC = binary:decode_hex(<<"5d3e88816daf20f11018456b58b2614050b93b222f03be079b39a9bb2de49f47">>),
        {C, MAC} = libsodium_crypto_aead_aegis128l:encrypt_detached(M, AD, N, K),
        CT = <<C/binary, MAC/binary>>,
        CT = libsodium_crypto_aead_aegis128l:encrypt(M, AD, N, K),
        M = libsodium_crypto_aead_aegis128l:decrypt(CT, AD, N, K),
        M = libsodium_crypto_aead_aegis128l:decrypt_detached(C, MAC, AD, N, K)
    end,
    ok.

-spec crypto_aead_aegis128l_round_trip_without_ad(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
crypto_aead_aegis128l_round_trip_without_ad(_Config) ->
    _ = begin
        K = libsodium_crypto_aead_aegis128l:keygen(),
        16 = byte_size(K),
        N = libsodium_randombytes:buf(16),
        M = libsodium_randombytes:buf(1000),
        CT = libsodium_crypto_aead_aegis128l:encrypt(M, N, K),
        1032 = byte_size(CT),
        CT = libsodium_crypto_aead_aegis128l:encrypt(M, <<>>, N, K),
        {C, MAC} = libsodium_crypto_aead_aegis128l:encrypt_detached(M, N, K),
        CT = <<C/binary, MAC/binary>>,
        M = libsodium_crypto_aead_aegis128l:decrypt(CT, N, K),
        M = libsodium_crypto_aead_aegis128l:decrypt_detached(C, MAC, N, K),
        <<>> = libsodium_crypto_aead_aegis128l:decrypt(libsodium_crypto_aead_aegis128l:encrypt(<<>>, N, K), N, K)
    end,
    ok.

-spec crypto_aead_aegis128l_tamper_and_badarg(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
crypto_aead_aegis128l_tamper_and_badarg(_Config) ->
    _ = begin
        K = libsodium_crypto_aead_aegis128l:keygen(),
        N = libsodium_randombytes:buf(16),
        <<B, Rest/binary>> = libsodium_crypto_aead_aegis128l:encrypt(<<"message">>, <<"ad">>, N, K),
        -1 = libsodium_crypto_aead_aegis128l:decrypt(<<(B bxor 1), Rest/binary>>, <<"ad">>, N, K),
        -1 = libsodium_crypto_aead_aegis128l:decrypt(<<B, Rest/binary>>, <<"other">>, N, K),
        -1 = libsodium_crypto_aead_aegis128l:decrypt(<<"short">>, N, K),
        -1 = libsodium_crypto_aead_aegis128l:decrypt_detached(<<"message">>, <<0:256>>, N, K),
        badarg =
            try
                libsodium_crypto_aead_aegis128l:encrypt(<<"m">>, <<0:96>>, K)
            catch
                error:badarg -> badarg
            end,
        badarg =
            try
                libsodium_crypto_aead_aegis128l:decrypt_detached(<<"m">>, <<0:128>>, N, K)
            catch
                error:badarg -> badarg
            end,
        badarg =
            try
                libsodium_crypto_aead_aegis128l:decrypt(not_a_binary, N, K)
            catch
                error:badarg -> badarg
            end
    end,
    ok.

