-spec crypto_core_keccak1600_sponge_matches_shake256(Config) -> Result when
    Config :: ct_suite:ct_config(), Result :: ok.
crypto_core_keccak1600_sponge_matches_shake256(_Config) ->
    _ = begin
        Mod = libsodium_crypto_core_keccak1600,
        Rate = 136,
        In = binary:copy(<<"keccak">>, 33),
        Padded0 = <<In/binary, 16#1F, 0:((2 * Rate - byte_size(In) - 1) * 8)>>,
        <<Head:(2 * Rate - 1)/binary, Last>> = Padded0,
        Padded = <<Head/binary, (Last bor 16#80)>>,
        <<Block1:Rate/binary, Block2:Rate/binary>> = Padded,
        S1 = Mod:permute_24(Mod:xor_bytes(Mod:init(), Block1, 0)),
        S2 = Mod:permute_24(Mod:xor_bytes(S1, Block2, 0)),
        Out1 = Mod:extract_bytes(S2, 0, Rate),
        Out2 = Mod:extract_bytes(Mod:permute_24(S2), 0, 64),
        Expected = crypto:hash_xof(shake256, In, (Rate + 64) * 8),
        Expected = <<Out1/binary, Out2/binary>>
    end,
    ok.

-spec crypto_core_keccak1600_xor_extract_round_trip(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
crypto_core_keccak1600_xor_extract_round_trip(_Config) ->
    _ = begin
        Mod = libsodium_crypto_core_keccak1600,
        Zero = Mod:init(),
        true = is_reference(Zero),
        Data = <<"0123456789">>,
        S1 = Mod:xor_bytes(Zero, Data, 5),
        Data = Mod:extract_bytes(S1, 5, 10),
        <<0:40, Data:10/binary, 0:1480>> = Mod:extract_bytes(S1, 0, 200),
        S2 = Mod:xor_bytes(S1, Data, 5),
        <<0:1600>> = Mod:extract_bytes(S2, 0, 200),
        <<0:1600>> = Mod:extract_bytes(Zero, 0, 200),
        Tail = <<16#AA, 16#55>>,
        Tail = Mod:extract_bytes(Mod:xor_bytes(Zero, Tail, 198), 198, 2),
        <<>> = Mod:extract_bytes(Zero, 200, 0),
        Same = Mod:xor_bytes(Zero, <<>>, 200),
        <<0:1600>> = Mod:extract_bytes(Same, 0, 200)
    end,
    ok.

