-spec crypto_secretstream_xchacha20poly1305_round_trip(Config) -> Result when
    Config :: ct_suite:ct_config(), Result :: ok.
crypto_secretstream_xchacha20poly1305_round_trip(_Config) ->
    _ = begin
        Mod = libsodium_crypto_secretstream_xchacha20poly1305,
        K = Mod:keygen(),
        {S0, Header} = Mod:init_push(K),
        true = is_reference(S0),
        24 = byte_size(Header),
        {S1, C1} = Mod:push(S0, <<"first">>, <<"ad1">>, Mod:tag_message()),
        22 = byte_size(C1),
        {S2, C2} = Mod:push(S1, <<>>, <<>>, Mod:tag_push()),
        S3 = Mod:rekey(S2),
        {S4, C3} = Mod:push(S3, <<"after rekey">>, <<>>, Mod:tag_rekey()),
        {_, C4} = Mod:push(S4, <<"last">>, <<>>, Mod:tag_final()),
        P0 = Mod:init_pull(Header, K),
        {P1, <<"first">>, 0} = Mod:pull(P0, C1, <<"ad1">>),
        {P2, <<>>, 1} = Mod:pull(P1, C2, <<>>),
        P3 = Mod:rekey(P2),
        {P4, <<"after rekey">>, 2} = Mod:pull(P3, C3, <<>>),
        {_, <<"last">>, 3} = Mod:pull(P4, C4, <<>>)
    end,
    ok.

