-spec crypto_xof_turboshake256_badarg(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
crypto_xof_turboshake256_badarg(_Config) ->
    _ = begin
        Mod = libsodium_crypto_xof_turboshake256,
        S0 = Mod:init(),
        badarg =
            try
                Mod:crypto_xof_turboshake256(-1, <<"x">>)
            catch
                error:badarg -> badarg
            end,
        badarg =
            try
                Mod:crypto_xof_turboshake256(32, not_a_binary)
            catch
                error:badarg -> badarg
            end,
        badarg =
            try
                Mod:init_with_domain(256)
            catch
                error:badarg -> badarg
            end,
        badarg =
            try
                Mod:init_with_domain(-1)
            catch
                error:badarg -> badarg
            end,
        badarg =
            try
                Mod:update(<<0:2048>>, <<"x">>)
            catch
                error:badarg -> badarg
            end,
        badarg =
            try
                Mod:update(S0, not_a_binary)
            catch
                error:badarg -> badarg
            end,
        badarg =
            try
                Mod:squeeze(<<0:2048>>, 32)
            catch
                error:badarg -> badarg
            end,
        badarg =
            try
                Mod:squeeze(S0, -1)
            catch
                error:badarg -> badarg
            end
    end,
    ok.

-spec randombytes_constants(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
randombytes_constants(_Config) ->
    _ = begin
        32 = libsodium_randombytes:seedbytes()
    end,
    ok.

-spec randombytes_example(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
randombytes_example(_Config) ->
    _ = begin
        Bytes = libsodium_randombytes:buf(32),
        32 = byte_size(Bytes),
        Roll = libsodium_randombytes:uniform(6),
        true = Roll >= 0 andalso Roll < 6
    end,
    ok.

-spec runtime_example(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
runtime_example(_Config) ->
    _ = begin
        Flags = [libsodium_runtime:has_sse2(), libsodium_runtime:has_avx2(), libsodium_runtime:has_neon()],
        true = lists:all(fun(Flag) -> Flag =:= 0 orelse Flag =:= 1 end, Flags)
    end,
    ok.

-spec runtime_flags(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
runtime_flags(_Config) ->
    _ = begin
        Flags = [
            libsodium_runtime:F()
         || F <- [
                has_neon,
                has_armcrypto,
                has_sse2,
                has_sse3,
                has_ssse3,
                has_sse41,
                has_avx,
                has_avx2,
                has_avx512f,
                has_pclmul,
                has_aesni,
                has_rdrand
            ]
        ],
        true = lists:all(fun(Flag) -> Flag =:= 0 orelse Flag =:= 1 end, Flags),
        true = (libsodium_runtime:has_neon() =:= 0) orelse (libsodium_runtime:has_sse2() =:= 0),
        true = (libsodium_runtime:has_avx2() =< libsodium_runtime:has_avx())
    end,
    ok.

-spec utils_example(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
utils_example(_Config) ->
    _ = begin
        Hex = libsodium_utils:bin2hex(<<"hi">>),
        <<"6869">> = Hex,
        <<"hi">> = libsodium_utils:hex2bin(Hex),
        <<"aGk">> = libsodium_utils:bin2base64(<<"hi">>, urlsafe_no_padding),
        <<"hi">> = libsodium_utils:base642bin(<<"aGk">>, urlsafe_no_padding),
        <<1, 1>> = libsodium_utils:increment(<<0, 1>>),
        0 = libsodium_utils:memcmp(<<"secret">>, <<"secret">>)
    end,
    ok.

-spec utils_hex_and_ip(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
utils_hex_and_ip(_Config) ->
    _ = begin
        Bin = libsodium_randombytes:buf(33),
        Hex = libsodium_utils:bin2hex(Bin),
        Hex = string:lowercase(binary:encode_hex(Bin)),
        Bin = libsodium_utils:hex2bin(Hex),
        Bin = libsodium_utils:hex2bin(binary:encode_hex(Bin)),
        <<>> = libsodium_utils:bin2hex(<<>>),
        <<>> = libsodium_utils:hex2bin(<<>>),
        <<16#de, 16#ad, 16#be, 16#ef>> = libsodium_utils:hex2bin(<<"de:ad be:EF">>, <<": ">>),
        -1 = libsodium_utils:hex2bin(<<"de:ad">>),
        -1 = libsodium_utils:hex2bin(<<"0g">>),
        -1 = libsodium_utils:hex2bin(<<"abc">>),
        V4 = libsodium_utils:ip2bin(<<"192.168.1.20">>),
        <<0:80, 16#ffff:16, 192, 168, 1, 20>> = V4,
        <<"192.168.1.20">> = libsodium_utils:bin2ip(V4),
        V6 = libsodium_utils:ip2bin(<<"2001:DB8::1">>),
        <<16#2001:16, 16#db8:16, 0:80, 1:16>> = V6,
        <<"2001:db8::1">> = libsodium_utils:bin2ip(V6),
        -1 = libsodium_utils:ip2bin(<<"256.0.0.1">>),
        badarg =
            try
                libsodium_utils:bin2ip(<<1, 2, 3>>)
            catch
                error:badarg -> badarg
            end
    end,
    ok.

-spec utils_base64(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
utils_base64(_Config) ->
    _ = begin
        [original, original_no_padding, urlsafe, urlsafe_no_padding] = Variants = libsodium_utils:base64_variants(),
        Options = #{
            original => #{},
            original_no_padding => #{padding => false},
            urlsafe => #{mode => urlsafe},
            urlsafe_no_padding => #{mode => urlsafe, padding => false}
        },
        [
            begin
                Bin = libsodium_randombytes:buf(Len),
                B64 = base64:encode(Bin, maps:get(Variant, Options)),
                B64 = libsodium_utils:bin2base64(Bin, Variant),
                Bin = libsodium_utils:base642bin(B64, Variant),
                Bin = libsodium_utils:base642bin(B64, <<>>, Variant),
                true = libsodium_utils:base64_encoded_len(Len, Variant) =:= byte_size(B64) + 1
            end
         || Variant <- Variants, Len <- lists:seq(0, 10)
        ],
        <<"aGVsbG8=">> = libsodium_utils:bin2base64(<<"hello">>),
        <<"hello">> = libsodium_utils:base642bin(<<"aGVsbG8=">>),
        <<"hello">> = libsodium_utils:base642bin(<<"aG Vs\nbG8=">>, <<" \n">>, 1),
        <<"aGVsbG8">> = libsodium_utils:bin2base64(<<"hello">>, 3),
        <<"-_8=">> = libsodium_utils:bin2base64(<<16#fb, 16#ff>>, 5),
        <<"-_8">> = libsodium_utils:bin2base64(<<16#fb, 16#ff>>, 7),
        -1 = libsodium_utils:base642bin(<<"aGVsbG8">>),
        -1 = libsodium_utils:base642bin(<<"aGVsbG8=">>, urlsafe_no_padding),
        -1 = libsodium_utils:base642bin(<<"-_8=">>, original),
        badarg =
            try
                libsodium_utils:bin2base64(<<"x">>, bogus)
            catch
                error:badarg -> badarg
            end,
        badarg =
            try
                libsodium_utils:bin2base64(<<"x">>, 2)
            catch
                error:badarg -> badarg
            end,
        badarg =
            try
                libsodium_utils:base64_encoded_len(1, 0)
            catch
                error:badarg -> badarg
            end
    end,
    ok.

-spec utils_pad(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
utils_pad(_Config) ->
    _ = begin
        <<"abc", 16#80>> = P1 = libsodium_utils:pad(<<"abc">>, 4),
        <<"abc">> = libsodium_utils:unpad(P1, 4),
        <<"abcd", 16#80, 0, 0, 0>> = P2 = libsodium_utils:pad(<<"abcd">>, 4),
        <<"abcd">> = libsodium_utils:unpad(P2, 4),
        <<16#80, 0:120>> = P3 = libsodium_utils:pad(<<>>, 16),
        <<>> = libsodium_utils:unpad(P3, 16),
        Msg = libsodium_randombytes:buf(100),
        P4 = libsodium_utils:pad(Msg, 7),
        105 = byte_size(P4),
        Msg = libsodium_utils:unpad(P4, 7),
        -1 = libsodium_utils:unpad(<<"abcd">>, 4),
        -1 = libsodium_utils:unpad(<<"abc", 16#80>>, 8),
        -1 = libsodium_utils:unpad(<<"abc", 16#80>>, 0),
        badarg =
            try
                libsodium_utils:pad(<<"abc">>, 0)
            catch
                error:badarg -> badarg
            end
    end,
    ok.

-spec utils_numbers(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
utils_numbers(_Config) ->
    _ = begin
        <<1, 0>> = libsodium_utils:increment(<<0, 0>>),
        <<0, 1>> = libsodium_utils:increment(<<255, 0>>),
        <<0, 0>> = libsodium_utils:increment(<<255, 255>>),
        <<>> = libsodium_utils:increment(<<>>),
        <<0, 1>> = libsodium_utils:add(<<255, 0>>, <<1, 0>>),
        <<1, 0>> = libsodium_utils:add(<<255, 255>>, <<2, 0>>),
        <<255, 0>> = libsodium_utils:sub(<<0, 1>>, <<1, 0>>),
        <<255, 255>> = libsodium_utils:sub(<<0, 0>>, <<1, 0>>),
        1 = libsodium_utils:compare(<<1, 2>>, <<2, 1>>),
        -1 = libsodium_utils:compare(<<2, 1>>, <<1, 2>>),
        0 = libsodium_utils:compare(<<3, 4>>, <<3, 4>>),
        1 = libsodium_utils:is_zero(<<0, 0, 0>>),
        0 = libsodium_utils:is_zero(<<0, 1, 0>>),
        0 = libsodium_utils:memcmp(<<"abc">>, <<"abc">>),
        -1 = libsodium_utils:memcmp(<<"abc">>, <<"abd">>),
        badarg =
            try
                libsodium_utils:compare(<<1>>, <<1, 2>>)
            catch
                error:badarg -> badarg
            end,
        badarg =
            try
                libsodium_utils:memcmp(<<1>>, <<>>)
            catch
                error:badarg -> badarg
            end,
        badarg =
            try
                libsodium_utils:add(<<1>>, <<1, 2>>)
            catch
                error:badarg -> badarg
            end,
        badarg =
            try
                libsodium_utils:sub(<<1, 2>>, <<1>>)
            catch
                error:badarg -> badarg
            end
    end,
    ok.

-spec version_constants(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
version_constants(_Config) ->
    _ = begin
        <<"1.0.22">> = libsodium_version:version_string(),
        26 = libsodium_version:library_version_major(),
        4 = libsodium_version:library_version_minor()
    end,
    ok.

-spec version_example(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
version_example(_Config) ->
    _ = begin
        <<"1.", _/binary>> = libsodium_version:version_string(),
        true = libsodium_version:library_version_major() >= 10
    end,
    ok.

-spec version_consistent(Config) -> Result when Config :: ct_suite:ct_config(), Result :: ok.
version_consistent(_Config) ->
    _ = begin
        Version = libsodium_version:version_string(),
        [_, _, _] = binary:split(Version, <<".">>, [global]),
        true = lists:member(libsodium_version:library_minimal(), [0, 1])
    end,
    ok.
